  // 1. Logos appear
  const logoEntrance = spring({
    frame: frame - 10,
    fps,
    config: springConfig,
  });

  // 2. Lines draw
  const lineProgress = spring({
    frame: frame - 40,
    fps,
    config: { ...springConfig, damping: 20 },
  });
  
  // 3. Bottom Banner appears
